<script setup lang="ts">import{ref,onMounted,computed}from'vue';import{http}from'@/shared/api/httpClient';const pendientes=ref<any[]>([]),abonadas=ref<any[]>([]),tab=ref<'pendientes'|'abonadas'>('pendientes'),clienteFiltro=ref('');const money=(v:number)=>v.toLocaleString('es-AR',{style:'currency',currency:'ARS'});const norm=(v:string)=>v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const visible=computed(()=>{const source=tab.value==='pendientes'?pendientes.value:abonadas.value,q=norm(clienteFiltro.value.trim());return !q?source:source.filter(c=>norm(c.cliente).includes(q))});async function load(){const[p,a]=await Promise.all([http.get('/cuotas/pendientes'),http.get('/cuotas/abonadas')]);pendientes.value=p.data;abonadas.value=a.data}async function pagar(c:any){const value=prompt(`Pago para ${c.tipoCesped} · compra ${c.fechaVenta}\nCuota #${c.numero}`,String(c.importePactado-c.importePagado));if(!value)return;await http.post(`/cuotas/${c.id}/pagos`,{importe:Number(value),medioPago:'Transferencia',fechaPago:new Date().toISOString().slice(0,10)});await load()}onMounted(load);</script>
<template><section class="page"><div class="page-title"><div><h2>Cuotas</h2><p>Seguimiento de cobranza por cliente y compra.</p></div></div><div class="cuotas-tabs"><button :class="{active:tab==='pendientes'}" @click="tab='pendientes'">Por pagar <span>{{pendientes.length}}</span></button><button :class="{active:tab==='abonadas'}" @click="tab='abonadas'">Abonadas <span>{{abonadas.length}}</span></button></div><div class="card cuotas-filter"><label>Buscar cliente</label><input v-model="clienteFiltro" type="search" placeholder="Nombre o apellido"><small>{{visible.length}} cuotas</small></div><div class="panel"><table><thead><tr><th>Cliente</th><th>Compra</th><th>Cuota</th><th>{{tab==='pendientes'?'Vencimiento':'Fecha de pago'}}</th><th>{{tab==='pendientes'?'Pactado':'Importe abonado'}}</th><th v-if="tab==='abonadas'">Impactado en sistema</th><th>Estado</th><th v-if="tab==='pendientes'"></th></tr></thead><tbody><tr v-for="c in visible" :key="c.id"><td><b>{{c.cliente}}</b></td><td><b>{{c.tipoCesped}}</b><br><small>{{c.fechaVenta}} · {{money(c.totalVenta)}}<br>Venta {{c.ventaId.slice(0,8).toUpperCase()}}</small></td><td>#{{c.numero}}</td><td>{{tab==='pendientes'?c.fechaVencimiento:c.fechaPago}}</td><td>{{money(tab==='pendientes'?c.importePactado:c.importePagado)}}</td><td v-if="tab==='abonadas'">{{new Date(c.fechaImpacto).toLocaleString('es-AR')}}<br><small>{{c.medioPago}}</small></td><td><span class="badge" :class="{warn:tab==='pendientes'}">{{c.estado}}</span></td><td v-if="tab==='pendientes'"><button class="btn" @click="pagar(c)">Registrar pago</button></td></tr></tbody></table><div v-if="!visible.length" class="empty">No hay cuotas en esta sección para ese cliente.</div></div></section></template>
